      const statusEl = figure.querySelector('[data-mech-status]');
      const stageButtons = [...figure.querySelectorAll('[data-stage-btn]')];
      const svgNodes = [...figure.querySelectorAll('[data-node-stage]')];

      const stageCopy = {
        all: ['All stages', 'Signals flow from Planner -> Executor -> Verifier -> Commit, or loop back from Verifier to Planner on check failure.'],
        planner: ['1. Planner', 'Defines the next plan and sends work forward to Executor; also receives retry feedback when verification fails.'],
        executor: ['2. Executor', 'Receives the plan from Planner, performs the work, and hands output to Verifier.'],
        verifier: ['3. Verifier', 'Runs checks on Executor output; advances to Commit on pass or routes back to Planner on check failure.'],
        commit: ['4. Commit', 'Finalizes verified output once Verifier checks pass.'],
        retry: ['Retry loop', 'Triggered on Verifier check failure; routes back to Planner for another pass through the loop.'],
      };

      const setStatus = (heading, detail) => {
        statusEl.textContent = '';
        const strong = document.createElement('strong');
        strong.textContent = heading + ': ';
        statusEl.append(strong, document.createTextNode(detail));
      };

      const setPaused = (paused, announce = true) => {
        figure.dataset.paused = String(paused);
        toggleBtn.setAttribute('aria-pressed', String(paused));
        toggleBtn.textContent = paused ? 'Play animation' : 'Pause animation';
        if (typeof svg.pauseAnimations === 'function') {
          if (paused) svg.pauseAnimations();
          else svg.unpauseAnimations();
        }
        if (announce) {
          setStatus(
            paused ? 'Animation paused' : 'Animation playing',
            paused
              ? 'Motion is paused; static directional arrows and numbered stages remain visible.'
              : 'Signal streams resumed along the primary and retry paths.'
          );
        }
      };

      const setStage = (stageKey) => {
        const key = stageCopy[stageKey] ? stageKey : 'all';
        figure.dataset.activeStage = key;
        for (const btn of stageButtons) {
          btn.setAttribute('aria-pressed', String(btn.dataset.stageBtn === key));
        }
        const [title, detail] = stageCopy[key];
        setStatus(title, detail);
      };

      const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
      if (reducedMotion.matches) {
        setPaused(true, false);
        setStatus(
          'Reduced motion active',
          'Continuous signal animation is disabled; directional arrows and numbered stages show the full loop statically.'
        );
      }

      toggleBtn.addEventListener('click', () => {
        setPaused(figure.dataset.paused !== 'true', true);
      });

      for (const btn of stageButtons) {
        btn.addEventListener('click', () => setStage(btn.dataset.stageBtn));
      }

      for (const node of svgNodes) {
        const activate = () => setStage(node.dataset.nodeStage);
        node.addEventListener('click', activate);
        node.addEventListener('focus', activate);
        node.addEventListener('keydown', (event) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            activate();
          }
        });
      }
    })();
